CREATE TABLE IF NOT EXISTS workforce_role_templates(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,role_code TEXT NOT NULL,display_name TEXT NOT NULL,access_blueprint_json TEXT NOT NULL DEFAULT '[]',custody_blueprint_json TEXT NOT NULL DEFAULT '[]',locked INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,role_code));
CREATE TABLE IF NOT EXISTS workforce_employee_actions(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,employee_email TEXT NOT NULL,action_type TEXT NOT NULL CHECK(action_type IN('COACHING','CORRECTIVE_ACTION','WRITTEN_WARNING','FINAL_WARNING','TERMINATION_RECOMMENDATION')),summary TEXT NOT NULL,policy_reference TEXT,evidence_json TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'DRAFT',approval_status TEXT NOT NULL DEFAULT 'PENDING',document_object_key TEXT,created_by TEXT NOT NULL,approved_by TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workforce_publishing_targets(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,target_key TEXT NOT NULL,display_name TEXT NOT NULL,connection_status TEXT NOT NULL DEFAULT 'CREDENTIALS_REQUIRED',approval_required INTEGER NOT NULL DEFAULT 1,last_published_at TEXT,UNIQUE(organization_id,property_id,target_key));
CREATE TABLE IF NOT EXISTS workforce_job_publication_drafts(id TEXT PRIMARY KEY,requisition_id TEXT NOT NULL,target_key TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'DRAFT',approval_status TEXT NOT NULL DEFAULT 'PENDING',external_reference TEXT,published_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(requisition_id) REFERENCES workforce_job_requisitions(id));
CREATE TABLE IF NOT EXISTS workforce_offboarding_tasks(id TEXT PRIMARY KEY,separation_case_id TEXT NOT NULL,task_type TEXT NOT NULL,resource_reference TEXT NOT NULL,execution_mode TEXT NOT NULL DEFAULT 'MANUAL_PROVIDER_ACTION',status TEXT NOT NULL DEFAULT 'OPEN',completed_by TEXT,completed_at TEXT,evidence_json TEXT NOT NULL DEFAULT '{}',FOREIGN KEY(separation_case_id) REFERENCES workforce_separation_cases(id));
CREATE INDEX IF NOT EXISTS idx_workforce_actions_scope ON workforce_employee_actions(organization_id,property_id,employee_email,status);
CREATE INDEX IF NOT EXISTS idx_workforce_publication_requisition ON workforce_job_publication_drafts(requisition_id,status);
